var request = new MessageBuilder()
                 .WithContent("Hello, world!")
                 .AddEmbed(e => e.WithTitle("Embed Title").WithDescription("Some text").WithColor(0x5865F2))
                 .WithReply(1234567890ul)
                 .WithAllowedMentions(AllowedMentions.PingRepliedUser)
                 .Build();

             await client.Rest.CreateMessageAsync(channelId, request);

var poll = new PollBuilder()
                .WithQuestion("What is your favourite colour?")
                .AddAnswer("Red", emojiName: "❤️")
                .AddAnswer("Blue", emojiName: "💙")
                .WithDuration(24)
                .AllowMultiselect()
                .Build();
            await client.CreatePollAsync(channelId, poll);

var role = new RoleBuilder()
                .WithName("Moderator")
                .WithColor(0xFF5733)
                .WithPermissions("8")          // Administrator
                .WithHoist()
                .WithMentionable()
                .Build();
            await client.CreateGuildRoleAsync(guildId, role);

var request = new WebhookExecuteBuilder()
                .WithContent("Hello from a webhook!")
                .WithUsername("CoolBot")
                .WithWait(true)
                .Build();
            await client.ExecuteWebhookAsync(webhookId, token, request);
